namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.",
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.",
            AverageRating = 4.7, RatingCount = 15
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Ingredients = "Basmati rice, Mixed vegetables, Onions, Biryani masala, Saffron, Ghee, Mint, Cilantro",
            Steps = "1. Soak rice for 30 minutes.\n2. Fry onions until golden.\n3. Cook vegetables with biryani masala.\n4. Layer rice and vegetables in a pot.\n5. Add saffron milk and ghee.\n6. Cook on low heat (dum) for 25 minutes.",
            AverageRating = 4.3, RatingCount = 8
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning",
            Steps = "1. Brown ground beef and drain fat.\n2. Add taco seasoning and water, simmer.\n3. Warm taco shells in oven.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomato, cheese.\n6. Add sour cream and serve.",
            AverageRating = 4.2, RatingCount = 10
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Mix all ingredients together.\n5. Add lime juice and salt to taste.\n6. Serve immediately with chips.",
            AverageRating = 4.6, RatingCount = 18
        },
        new Recipe
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold chocolate mixture into eggs.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12-14 minutes.",
            AverageRating = 4.9, RatingCount = 25
        },
        new Recipe
        {
            Id = 8, Title = "Miso Soup", Category = "Japanese",
            Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions",
            Steps = "1. Heat dashi stock until simmering.\n2. Cube tofu into small pieces.\n3. Rehydrate wakame in water.\n4. Dissolve miso paste into the stock.\n5. Add tofu and wakame.\n6. Garnish with sliced green onions.",
            AverageRating = 4.1, RatingCount = 7
        }
    };

    public static IEnumerable<string> GetCategories() =>
        Recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> GetByCategory(string category) =>
        Recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) =>
        Recipes.FirstOrDefault(r => r.Id == id);
}

@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community - Home</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeStore.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeStore.GetByCategory(category).Count() recipes</p>
                    <a href="recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-5">
    <h2>Share Your Recipes</h2>
    <p>Have a great recipe to share? Submit it to our community!</p>
    <a href="submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

<div class="row mt-3">
    @foreach (var recipe in RecipeStore.GetByCategory(Category))
    {
        <div class="col-md-6 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">
                        ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                    </p>
                    <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary">@recipe.Category</span>

    <div class="mt-4">
        <h3>Rate This Recipe</h3>
        <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="mt-4">
        <h3>Ingredients</h3>
        <ul class="list-group">
            @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>
    </div>

    <div class="mt-4">
        <h3>Steps</h3>
        <ol class="list-group list-group-numbered">
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                var text = step.Contains('.') ? step[(step.IndexOf('.') + 1)..].Trim() : step;
                <li class="list-group-item">@text</li>
            }
        </ol>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= currentRating ? "★" : "☆")
        </span>
    }
    @if (hasRated)
    {
        <span class="ms-2 text-success">Thanks! You rated this @currentRating star@(currentRating > 1 ? "s" : "").</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click to rate</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 2rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;
    private bool hasRated;

    private void Rate(int rating)
    {
        currentRating = rating;
        hasRated = true;
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@model.Title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeStore.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5"
                placeholder="One ingredient per line" />
            <ValidationMessage For="() => model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6"
                placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private bool submitted;

    private void HandleSubmit()
    {
        submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

