@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary">@recipe.Category</span>

    <div class="mt-4">
        <h3>Rate This Recipe</h3>
        <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="mt-4">
        <h3>Ingredients</h3>
        <ul class="list-group">
            @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>
    </div>

    <div class="mt-4">
        <h3>Steps</h3>
        <ol class="list-group list-group-numbered">
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                var text = step.Contains('.') ? step[(step.IndexOf('.') + 1)..].Trim() : step;
                <li class="list-group-item">@text</li>
            }
        </ol>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= currentRating ? "★" : "☆")
        </span>
    }
    @if (hasRated)
    {
        <span class="ms-2 text-success">Thanks! You rated this @currentRating star@(currentRating > 1 ? "s" : "").</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click to rate</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 2rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;
    private bool hasRated;

    private void Rate(int rating)
    {
        currentRating = rating;
        hasRated = true;
    }
}

