@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community - Home</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeStore.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeStore.GetByCategory(category).Count() recipes</p>
                    <a href="recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-5">
    <h2>Share Your Recipes</h2>
    <p>Have a great recipe to share? Submit it to our community!</p>
    <a href="submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

